let LANG = 'ca';
try { const s = localStorage.getItem('quizsolde.lang'); if (s && I18N[s]) LANG = s; } catch { }

function setLang(code) {
  if (!I18N[code]) return;
  LANG = code;
  try { localStorage.setItem('quizsolde.lang', code); } catch { }
}

/** Traduce una clave (con respaldo en catalán); {nombre} se sustituye por vars.nombre tal cual (escapa antes el texto del usuario). */
function t(key, vars) {
  let s = I18N[LANG][key] ?? I18N.ca[key] ?? key;
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m));
  return s;
}

/** Traducción con plural: usa clave.one / .few / .many / .other según las reglas del idioma. */
function tn(key, n, vars) {
  let cat = 'other';
  try { cat = new Intl.PluralRules(LANG === 'tlh' ? 'en' : LANG).select(n); } catch { }
  const d = I18N[LANG];
  const k = (key + '.' + cat) in d ? key + '.' + cat : key + '.other';
  return t(k, { n, ...vars });
}

